// Joins src/webpush.js and src/index.js into dist/worker.js, a single file
// that can be pasted into the Cloudflare dashboard's code editor: `npm run bundle`.
// `node scripts/bundle.js --check` fails if dist/worker.js is out of date.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const read = name => readFileSync(new URL(`../src/${name}`, import.meta.url), 'utf8');
// Only the default export may remain: Cloudflare treats other exports as
// entry points.
const strip = code => code
  .replace(/^import .*$\n/gm, '')
  .replace(/^export (async )?function /gm, (_, a) => `${a || ''}function `);

export function bundle() {
  return [
    '// SwasthID reminder Worker, as one file for the Cloudflare dashboard.',
    '// Generated by `npm run bundle` from src/webpush.js and src/index.js; edit those instead.',
    '',
    '// ---- webpush.js ----',
    strip(read('webpush.js')),
    '// ---- index.js ----',
    strip(read('index.js')),
  ].join('\n');
}

const target = new URL('../dist/worker.js', import.meta.url);
if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(target, 'utf8'); } catch {}
    if (current !== bundle()) {
      console.error('dist/worker.js is out of date. Run `npm run bundle`.');
      process.exit(1);
    }
    console.log('dist/worker.js is up to date.');
  } else {
    mkdirSync(new URL('../dist/', import.meta.url), { recursive: true });
    writeFileSync(target, bundle());
    console.log('Wrote dist/worker.js');
  }
}
